{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection in dynamic query",
      "severity": "High",
      "file": "AccountSearchController.cls",
      "lines": "3-5",
      "explanation": "The method concatenates the user‑supplied searchKey directly into a dynamic SOQL string without escaping or binding, allowing an attacker to inject arbitrary SOQL clauses and potentially read or modify data beyond their permissions.",
      "remediation": "Rewrite the query to use bind variables or escape the input: e.g., `String query = 'SELECT Id, Name, Industry FROM Account WHERE Name LIKE :searchKey LIMIT 50';` or use `Database.queryWithBinds`. Ensure the searchKey is sanitized with `String.escapeSingleQuotes` if dynamic construction is unavoidable."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "Field-Level Security Violation in Contact Query",
      "severity": "Medium",
      "file": "ContactPhoneService.cls",
      "lines": "3-8",
      "explanation": "The method queries the Contact record for the Birthdate and Email fields without enforcing field‑level security. The permission set explicitly denies read access to Birthdate, so a user with this permission set can retrieve sensitive data they should not see.",
      "remediation": "Add FLS enforcement to the query, e.g., use `WITH SECURITY_ENFORCED` or `Security.stripInaccessible` after the query, or remove the sensitive fields from the SELECT clause. Ensure that any fields queried are granted read permission in the permission set or profile."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Record-level sharing bypass in @AuraEnabled method",
      "severity": "Medium",
      "file": "CaseHistoryController.cls",
      "lines": "1-12",
      "explanation": "The class is declared \"without sharing\", so record-level sharing rules are ignored. Because the method is exposed via @AuraEnabled, any user with the permission set can invoke it and retrieve cases they should not see, bypassing sharing restrictions.",
      "remediation": "Declare the class with \"with sharing\" or \"inherited sharing\", or add a WITH SHARE clause to the SOQL query. This ensures that only records the user is allowed to see are returned."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive permissions in Support Agent Tools permission set",
      "severity": "High",
      "file": "Support_Agent_Tools.permissionset-meta.xml",
      "lines": "all",
      "explanation": "The permission set grants ModifyAllData and ViewAllData, which allow users to bypass all sharing and field-level security on every object. This far exceeds the described purpose of only viewing and closing cases.",
      "remediation": "Remove the ModifyAllData and ViewAllData permissions from the permission set. Grant only the necessary Case object permissions (Read, Edit) and any other minimal permissions required for the support agent role."
    }
  ]
}
